// ELEMENTS:
// 1. Fundo navy com um brilho azul muito leve
// 2. Foto (src) dentro de uma janela em arco que abre de baixo para cima, zoom-out lento
// 3. Contorno azul IAD do arco a desenhar-se
// 4. Eyebrow + legenda em serifa branca
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#161617";
const NAVY_RGB = "22,22,23";
const CYAN = "#FFFFFF";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const JanelaArco: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };

  // The arch: a portrait window whose top is a half circle. Sized to fit the box.
  const archW = land ? Math.min(W * 0.36, H * 0.62) : format === "half" ? Math.min(W * 0.46, H * 0.5) : W * 0.68;
  const archH = land ? H * 0.8 : format === "half" ? H * 0.72 : H * 0.54;
  const r = archW / 2;
  const grow = show(0, 1.1); // the window opens from the bottom up
  const zoom = interpolate(f, [0, T], [1.16, 1.02], { ...clamp, easing: Easing.out(Easing.sin) });
  const gap = 16 * u;
  const R = r + gap; // the outline runs `gap` outside the window
  const oh = archH + gap;
  const outlineLen = 2 * (oh - R) + Math.PI * R;
  const outline = show(0.35, 1.2);

  const arch = (
    <div style={{ position: "relative", width: archW, height: archH, flex: "0 0 auto" }}>
      <svg width={2 * R} height={oh} style={{ position: "absolute", left: -gap, top: -gap, overflow: "visible" }}>
        <path
          d={`M 0 ${oh} L 0 ${R} A ${R} ${R} 0 0 1 ${2 * R} ${R} L ${2 * R} ${oh}`}
          fill="none"
          stroke={CYAN}
          strokeWidth={2 * u}
          strokeDasharray={outlineLen}
          strokeDashoffset={outlineLen * (1 - outline)}
        />
      </svg>
      <div style={{ position: "absolute", inset: 0, overflow: "hidden", borderRadius: `${r}px ${r}px 0 0`, clipPath: `inset(${(1 - grow) * 100}% 0 0 0)` }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)", transform: `scale(${zoom})` }} /> : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse at 50% 40%, rgba(255,255,255,0.06) 0%, rgba(${NAVY_RGB},0) 60%)` }} />
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: land ? "row" : "column",
          alignItems: "center",
          justifyContent: "center",
          gap: (land ? 110 : 80) * u,
          padding: land ? `0 ${120 * u}px` : `0 ${80 * u}px`,
          boxSizing: "border-box",
        }}
      >
        {arch}
        <div style={{ display: "flex", flexDirection: "column", alignItems: land ? "flex-start" : "center", textAlign: land ? "left" : "center", gap: 22 * u, maxWidth: land ? W * 0.4 : W * 0.84 }}>
          {eyebrow ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.7) }}>{eyebrow}</div>
          ) : null}
          {caption ? (
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 92 * u, lineHeight: 1.05, color: WHITE, ...rise(0.85) }}>{caption}</div>
          ) : null}
        </div>
      </div>
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default JanelaArco;
